edits.replacement:
#root #hub #firstkit{ display:none !important; }
/* v28.xx (cw-uc-stashhead) b-31 step 7, critic on 04 (P1 "subtitle repeats the xp, dashes banned"; "title is a tiny grey word"): the stash subtitle line is hidden, the title is 32px; the xp still shows in the header stats. Looks only. */
#root #hub .toprow .brand + div{ display:none !important; }
#root #hub .toprow .brand{ font-size:32px !important; }

check:
{v:'VER',what:'the stash header has no dash subtitle and a 32px title',
 run:function(){
   var bad=[];
   try{
     var b=document.querySelector('#hub .toprow .brand'), s=b&&b.nextElementSibling;
     if(!b) bad.push('no brand'); else {
       if(parseFloat(getComputedStyle(b).fontSize)<31.5) bad.push('title is '+getComputedStyle(b).fontSize);
       if(s&&getComputedStyle(s).display!=='none') bad.push('subtitle displays'); }
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   return bad.length?bad.join('; '):null; }},
